contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // first call: optionally deposit 'd1' wei (will be sent with Deposit call)
    // second call: attempt CashOut of amount 'co'
    function run(uint d1, uint co) public payable {
        require(address(this).balance >= d1, "insufficient test balance for d1");
        // record balances before any action
        uint before_contract_bal = address(c).balance;
        uint before_my_balance = c.balances(address(this));

        // Try Deposit with value d1 (Deposit only updates if d1 > MinDeposit inside C)
        bool dep_reverted = false;
        // call Deposit: it will silently do nothing if d1 <= MinDeposit; otherwise may revert on overflow (unlikely)
        try c.Deposit{value: d1}() {
            dep_reverted = false;
        } catch {
            dep_reverted = true;
        }

        // read balances after deposit attempt
        uint after_deposit_contract_bal = address(c).balance;
        uint after_deposit_my_balance = c.balances(address(this));

        // Now attempt CashOut of co
        bool cash_reverted = false;
        try c.CashOut(co) {
            cash_reverted = false;
        } catch {
            cash_reverted = true;
        }

        // final observations
        uint final_contract_bal = address(c).balance;
        uint final_my_balance = c.balances(address(this));

        // Now assert the general invariant: any successful Deposit that updated balances must have increased both contract balance and recorded balances by the same amount;
        // any successful CashOut that returned successfully must have decreased both contract balance and recorded balances by the same amount.
        // We express this by relating observed deltas, guarded by whether the call reverted and by monotonicity

        // Compute deltas (use unsigned arithmetic in a way that avoids underflow by branching in logic below)
        // We assert: if Deposit didn't revert and contract balance increased, then the increase equals the increase in recorded balances; similarly for CashOut decrease.

        assert(
            // Deposit consistency: either deposit reverted or no net change in contract and recorded balances, or both increased by same amount
            (
                dep_reverted
                || (
                    (after_deposit_contract_bal == before_contract_bal && after_deposit_my_balance == before_my_balance)
                    || (after_deposit_contract_bal > before_contract_bal && after_deposit_my_balance > before_my_balance && (after_deposit_contract_bal - before_contract_bal) == (after_deposit_my_balance - before_my_balance))
                )
            )
            &&
            // CashOut consistency: either cashout reverted or no net change, or both decreased by same amount
            (
                cash_reverted
                || (
                    (final_contract_bal == after_deposit_contract_bal && final_my_balance == after_deposit_my_balance)
                    || (final_contract_bal < after_deposit_contract_bal && final_my_balance < after_deposit_my_balance && (after_deposit_contract_bal - final_contract_bal) == (after_deposit_my_balance - final_my_balance))
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // param: amount to attempt to withdraw via CashOut
    function run(uint am) public payable {
        // No precondition on am; ensure this contract can receive refunds if needed
        // Record observed balances before the CashOut attempt
        uint before_contract_bal = address(c).balance;
        uint before_recorded = c.balances(address(this));

        bool reverted;
        try c.CashOut(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after_contract_bal = address(c).balance;
        uint after_recorded = c.balances(address(this));

        // General rule: if caller's recorded balance < am then CashOut must either revert or leave both the recorded balance and contract balance unchanged.
        bool caller_insufficient = (before_recorded < am);

        assert(!caller_insufficient || reverted || (after_recorded == before_recorded && after_contract_bal == before_contract_bal));
    }

    receive() external payable {}
}

