contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to send with Deposit
    function run(uint amount) public payable {
        // ensure this contract holds enough ETH to forward
        require(address(this).balance >= amount, "insufficient test balance");

        // observe before values
        uint before_recorded = c.balances(address(this));
        uint before_contract_bal = address(c).balance;

        // call Deposit and catch revert
        bool reverted;
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after values
        uint after_recorded = c.balances(address(this));
        uint after_contract_bal = address(c).balance;

        // MinDeposit is public; read it
        uint minDep = c.MinDeposit();

        // General rule:
        // - If amount <= MinDeposit then Deposit must not change recorded balance nor contract balance (may still revert or not? Contract's Deposit uses `if(msg.value > MinDeposit)` so when <= it simply returns without state change and without revert). Therefore it must not revert and state unchanged.
        // - If amount > MinDeposit then Deposit must succeed (not revert) and both recorded and contract balances increase by exactly amount.

        // Construct assertion accordingly.
        assert(
            // case amount <= minDep: no revert and no change
            ((amount <= minDep) && !reverted && after_recorded == before_recorded && after_contract_bal == before_contract_bal)
            // case amount > minDep: no revert and both balances increase by amount
            || ((amount > minDep) && !reverted && after_recorded == before_recorded + amount && after_contract_bal == before_contract_bal + amount)
        );
    }

    // allow receiving ETH when c sends back (if ever)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to attempt to CashOut
    function run(uint _am) public payable {
        // ensure this test contract has ETH to fund prior deposits if needed
        // we will first deposit funds into c so that address(this) has a recorded balance >= _am in the contract
        // require enough ETH to fund the deposit
        require(address(this).balance >= _am + 1 wei, "not enough test ETH");

        // read before values
        uint before_recorded = c.balances(address(this));
        uint before_contract_bal = address(c).balance;

        // If current recorded balance is less than desired amount, top-up via Deposit with value = needed amount + 1 wei
        if (before_recorded < _am) {
            uint need = _am - before_recorded;
            // send at least MinDeposit when depositing; ensure we satisfy > MinDeposit to trigger Deposit logic
            uint minD = c.MinDeposit();
            uint send = need;
            if (send <= minD) {
                // make send > minD
                send = minD + 1;
            }
            // ensure we have enough balance
            require(address(this).balance >= send, "insufficient for top-up");
            // perform Deposit (may or may not revert depending on C implementation); we do not catch revert here because a revert would abort this test transaction and assertion won't be reached
            c.Deposit{value: send}();
            // update observed before values to reflect after deposit
            before_recorded = c.balances(address(this));
            before_contract_bal = address(c).balance;
        }

        // Now attempt CashOut with _am (we will catch revert)
        bool reverted;
        try c.CashOut{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint after_recorded = c.balances(address(this));
        uint after_contract_bal = address(c).balance;

        // General rule assertion:
        // If _am <= before_recorded then either
        //  - call reverted and both recorded balance and contract balance unchanged, OR
        //  - call did not revert and both recorded balance and contract balance decreased by exactly _am.
        assert(((_am <= before_recorded) && (
            (reverted && after_recorded == before_recorded && after_contract_bal == before_contract_bal)
            || (!reverted && after_recorded == before_recorded - _am && after_contract_bal == before_contract_bal - _am)
        )) || (_am > before_recorded));
        // Note: if _am > before_recorded we don't assert behavior (CashOut is allowed to do either nothing or revert), so test accepts any outcome in that case.
    }

    // allow receiving ETH when CashOut succeeds
    receive() external payable {}
}

