        }

        // Observe after state
        uint after_contract_balance = address(c).balance;
        uint after_mapping = c.balances(address(this));

        // General rule:
        // - If call reverted then both mapping and contract balance unchanged.
        // - Else (call did not revert): if depositAmount > c.MinDeposit() then mapping increased by depositAmount
        //   and contract balance increased by depositAmount; otherwise Deposit has no effect (mapping and balance unchanged).
        uint minDep = c.MinDeposit();
        assert(
            (
                deposit_reverted == true
                && after_mapping == before_mapping
                && after_contract_balance == before_contract_balance
            )
            ||
            (
                deposit_reverted == false
                && depositAmount > minDep
                && after_mapping == before_mapping + depositAmount
                && after_contract_balance == before_contract_balance + depositAmount
            )
            ||
            (
                deposit_reverted == false
                && depositAmount <= minDep
                && after_mapping == before_mapping
                && after_contract_balance == before_contract_balance
            )
        );
    }

    receive() external payable {}
}
